void look_0(inout Look k) {
  p_stColour = L0_stColour;
  p_stMetal = L0_stMetal;
  p_stRough = L0_stRough;
  p_stOil = L0_stOil;
  p_stOilColour = L0_stOilColour;
  p_stOilBrown = L0_stOilBrown;
  p_stOilSize = L0_stOilSize;
  p_stOilRough = L0_stOilRough;
  p_stFinPitch = L0_stFinPitch;
  p_stFinShare = L0_stFinShare;
  p_stFinDepth = L0_stFinDepth;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

void look_1(inout Look k) {
  p_ucColour = L1_ucColour;
  p_ucRough = L1_ucRough;
  p_ucGrime = L1_ucGrime;
  p_ucGrimeColour = L1_ucGrimeColour;
  p_ucDust = L1_ucDust;
  p_ucDustColour = L1_ucDustColour;
  p_ucChips = L1_ucChips;
  p_ucRust = L1_ucRust;
  p_ucOil = L1_ucOil;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float ucDown = smoothstep(0.0, -0.8, wn.y);
    float ucUp = smoothstep(0.3, 0.95, wn.y);
    float ucB = kfbm(uv * 4.0 + seed);
    float ucG = clamp(p_ucGrime * (0.3 + 0.9 * ucDown) * smoothstep(0.3, 0.75, ucB + 0.25 * ucDown), 0.0, 1.0);
    float ucD = clamp(p_ucDust * ucUp * smoothstep(0.35, 0.8, kfbm4(uv * 7.0 + seed + 4.0)), 0.0, 1.0);
    // chips gather in patches (a slow field) and are each a small blot (a fast one), so they cluster on a part
    float ucPatch = smoothstep(0.55, 0.8, kfbm4(uv * 1.5 + seed + 21.0));
    float ucChipN = (kn(uv * 70.0 + seed + 9.0) + 0.15 * kn(uv * 300.0 + seed)) * kfade(0.02);
    float ucChip = ucPatch * smoothstep(1.06 - 0.12 * p_ucChips, 1.1 - 0.12 * p_ucChips, ucChipN);
    float ucO = p_ucOil * smoothstep(0.55, 0.85, kfbm4(uv * 2.0 + seed + 11.0));
    k.colour = mix(p_ucColour, p_ucGrimeColour, ucG);
    k.colour = mix(k.colour, p_ucDustColour, ucD);
    k.colour = mix(k.colour, p_ucRust * (0.7 + 0.6 * kn(uv * 200.0 + seed)), ucChip);
    k.colour = mix(k.colour, vec3(0.01, 0.008, 0.006), ucO);
    k.rough = clamp(p_ucRough + 0.35 * ucG + 0.3 * ucD + 0.35 * ucChip - 0.4 * ucO, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00015 * ucG * ucB - 0.0001 * ucChip;

}



Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 0: look_0(k); break;
    case 1: look_1(k); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
      case 0: k.colour = vec3(0.019382360956935723, 0.22696587351009836, 0.7912979403326302); break;
      case 1: k.colour = vec3(0.017641954488384078, 0.01599629336550963, 0.012983032342173012); break;
    }
  }
  return k;
}
